param(
  [Parameter(Mandatory=$true)][int]$ParentPid,
  [Parameter(Mandatory=$true)][int]$HostPid,
  [Parameter(Mandatory=$true)][string]$InstallDir,
  [Parameter(Mandatory=$true)][string]$PayloadDir,
  [Parameter(Mandatory=$true)][string]$RestartExe,
  [Parameter(Mandatory=$true)][string]$StageDir,
  [Parameter(Mandatory=$true)][string]$RollbackDir,
  [Parameter(Mandatory=$true)][string]$ResultPath,
  [Parameter(Mandatory=$true)][string]$ReadyPath,
  [Parameter(Mandatory=$true)][string]$TargetVersion,
  [Parameter(Mandatory=$true)][string]$Flavor
)
$ErrorActionPreference = 'Stop'
function Assert-ChildPath([string]$parent, [string]$child) {
  $base = [IO.Path]::GetFullPath($parent).TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar)
  $full = [IO.Path]::GetFullPath($child)
  $prefix = $base + [IO.Path]::DirectorySeparatorChar
  if (!$full.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) { throw Desteklenen dizinin ötesinde bir yol: $full" }
  return $full
}
function Assert-Payload([string]$root, [string]$version, [string]$edition) {
  if (!(Test-Path -LiteralPath (Join-Path $root 'TypelessToolkit.exe')) -or !(Test-Path -LiteralPath (Join-Path $root 'servermanager.js')) -or !(Test-Path -LiteralPath (Join-Path $root 'serverpackage.json')) -or !(Test-Path -LiteralPath (Join-Path $root 'data'))) { throw 'The structure of the update package or installation directory is blank.'}
  try { $manifest = Get-Content -LiteralPath (Join-Path $root 'serverpackage.json') -Raw -Encoding UTF8 | ConvertFrom-Json } catch { throw 'server/package.json Okuyamazsın.”
  if ([string]$manifest.version -ne [string]$version) { throw 'Güncelleme paketi versiyonu ve hedef Release Inconsistent.'
  $node = Join-Path $root 'runtime
ode.exe'
  if ($edition -eq 'portable' -and !(Test-Path -LiteralPath $node)) { throw 'Portable Güncellemede gömülü çalışma zamanı eksik: Node.js。' }
  if ($edition -eq 'lite' -and (Test-Path -LiteralPath $node)) { throw 'Lite Güncelleme gömülü çalışma zamanı içeriyor: Node.js。' }
  if ($edition -ne 'portable' -and $edition -ne 'lite') { throw "Ben onaylayamıyorum. Windows Update package type.'}
}
function Write-Result([string]$state, [string]$message) {
  try {
    @{ state = $state; stage = 'install'; version = $TargetVersion; target_version = $TargetVersion; at = (Get-Date).ToUniversalTime().ToString('o'); message = $message } | ConvertTo-Json -Compress | Set-Content -LiteralPath $ResultPath -Encoding UTF8
  } catch { }
}
$install = [IO.Path]::GetFullPath($InstallDir)
if ($install.TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar) -eq [IO.Path]::GetPathRoot($install).TrimEnd([IO.Path]::DirectorySeparatorChar, [IO.Path]::AltDirectorySeparatorChar)) { throw 'Dejected disk kök rehberi güncel bir yükleme rehberi olarak.'}
$payload = Assert-ChildPath $StageDir $PayloadDir
$rollback = Assert-ChildPath $install $RollbackDir
$result = Assert-ChildPath (Join-Path $install 'data') $ResultPath
$ready = Assert-ChildPath $StageDir $ReadyPath
if ((Split-Path -Leaf $rollback) -notmatch '^.typeless-toolkit-update-rollback-[A-Za-z0-9]+$') { throw ‘Temporly geri çekilme rehberi geçersizdir.’
if ((Split-Path -Leaf $ready) -notmatch '^.typeless-toolkit-ready-[A-Za-z0-9]+.marker$') { throw 'Güncel Hazırlık etiketi adı geçersizdir.'
if (Test-Path -LiteralPath $rollback) { throw ‘Geçi geri çekilme rehberi zaten var, lütfen onu güncellemeye çalışın.’
if (Test-Path -LiteralPath $ready) { throw “Güncel hazırlık etiketi var, lütfen tekrar deneyin.”
if ([IO.Path]::GetFullPath($RestartExe) -ne (Join-Path $install 'TypelessToolkit.exe')) { throw "Reactivate programı yolu geçersizdir."
$deadline = (Get-Date).AddSeconds(75)
$rollbackStarted = $false
$oldMoveCompleted = $false
$replacementStarted = $false
$newProcess = $null
try {
  while ((Get-Process -Id $ParentPid -ErrorAction SilentlyContinue) -or (Get-Process -Id $HostPid -ErrorAction SilentlyContinue)) {
    if ((Get-Date) -gt $deadline) { throw "The old version of the carkit was not exit in 75 saniye; Lütfen manuel olarak bırakın ve tekrar deneyin."
    Start-Sleep -Milliseconds 250
  }
  Assert-Payload $payload $TargetVersion $Flavor
  $currentManifest = Get-Content -LiteralPath (Join-Path $install 'serverpackage.json') -Raw -Encoding UTF8 | ConvertFrom-Json
  $currentFlavor = if (Test-Path -LiteralPath (Join-Path $install 'runtime
ode.exe')) { 'portable' } else { 'lite' }
  Assert-Payload $install ([string]$currentManifest.version) $currentFlavor
  [IO.Directory]::CreateDirectory($rollback) | Out-Null
  $rollbackStarted = $true
  Get-ChildItem -LiteralPath $install -Force | Where-Object { $_.Name -ne 'data' -and $_.FullName -ne $rollback } | ForEach-Object {
    Move-Item -LiteralPath $_.FullName -Destination $rollback -Force
  }
  $oldMoveCompleted = $true
  $replacementStarted = $true
  Get-ChildItem -LiteralPath $payload -Force | Where-Object { $_.Name -ne 'data' } | ForEach-Object {
    Copy-Item -LiteralPath $_.FullName -Destination $install -Recurse -Force
  }
  Assert-Payload $install $TargetVersion $Flavor
  $newProcess = Start-Process -FilePath $RestartExe -WorkingDirectory $install -ArgumentList ('--toolkit-update-ready "{0}" --toolkit-update-version {1}' -f $ready, $TargetVersion) -PassThru
  $readyDeadline = (Get-Date).AddSeconds(30)
  while (!(Test-Path -LiteralPath $ready)) {
    if ($newProcess.HasExited) { throw “ Aracın yeni versiyonu başlamak için başarısız oldu, çıkış kodu $ ()newProcess.ExitCode)。" }
    if ((Get-Date) -gt $readyDeadline) { throw “Kar setinin yeni versiyonu onay için hazır değil.”
    Start-Sleep -Milliseconds 250
  }
  if ((Get-Content -LiteralPath $ready -Raw).Trim() -ne $TargetVersion) { throw “Yeni aletler seti, etiketin versiyonunu eşleştirmez.”
  Remove-Item -LiteralPath $rollback -Recurse -Force
  Write-Result 'succeeded“Güncellendirene v$TargetVersion。"
} catch {
  $message = $_.Exception.Message
  if ($newProcess -and !$newProcess.HasExited) { try { Stop-Process -Id $newProcess.Id -Force } catch { } }
  if ($rollbackStarted) {
    try {
      if ($oldMoveCompleted -and $replacementStarted) {
        Get-ChildItem -LiteralPath $install -Force | Where-Object { $_.Name -ne 'data' -and $_.FullName -ne $rollback } | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force }
      }
      Get-ChildItem -LiteralPath $rollback -Force | ForEach-Object { Move-Item -LiteralPath $_.FullName -Destination $install -Force }
      Remove-Item -LiteralPath $rollback -Recurse -Force
      Start-Process -FilePath $RestartExe -WorkingDirectory $install
      Write-Result 'rolled-back'Güncelleme başarısız oldu, orijinal versiyon restore edildi: $ $message"
    } catch {
      Write-Result 'failed"The update başarısız oldu ve orijinal versiyon başarısız oldu: $ $message；$($_.Exception.Message)"
    }
  } else { Write-Result 'failed"The update was not start to be replace: $message" }
}
$cleanup = 'timeout /t 5 /nobreak >nul & rmdir /s /q "' + $StageDir + '"'
Start-Process -FilePath $env:ComSpec -ArgumentList '/d', '/c', $cleanup -WindowStyle Hidden
